const demo_checkIfUrlIsCurrent = (url) => {
    if (url.charAt(0) === "/") {
        url = url.substring(1);
    }
    const base = window.location.href;
    const stack = base.split("/"), parts = url.split("/");
    stack.pop();
    for (let i = 0; i < parts.length; i++) {
        if (parts[i] == ".")
            continue;
        if (parts[i] == "..")
            stack.pop();
        else
            stack.push(parts[i]);
    }
    return stack.join("/") === window.location.href;
};

